// src/components/seo-guide/FaqHub.jsx
"use client";

import { useMemo, useState } from "react";
import GuideMarkdown from "./GuideMarkdown";
import { chipCls, h2Cls, h3Cls } from "./guideStyles";

// Searchable, filterable FAQ hub. Extends the static `faq` block with:
//   - Free-text search across every question + answer
//   - Category chips (each group in `block.groups` carries a `category`)
//   - Expand / collapse all
//   - Live count + empty state
//
// JSON-LD is still generated by GuidePage from `block.groups` — the shape
// mirrors the standard `faq` block so `generateFaqSchema` picks it up
// unchanged. Make sure GuidePage's FAQ filter includes `faqHub`.
export default function FaqHub({ block, live }) {
  const [query, setQuery] = useState("");
  const [activeCat, setActiveCat] = useState(block.categories[0].key);
  const [allOpen, setAllOpen] = useState(false);

  // Flatten every item once, tagging it with its group's category so
  // filtering is fast and the group can be re-derived on the fly.
  const flatItems = useMemo(
    () =>
      block.groups.flatMap((g, gi) =>
        g.items.map((it, ii) => ({
          id: `${gi}-${ii}`,
          groupIndex: gi,
          groupHeading: g.heading,
          category: g.category,
          q: it.q,
          a: it.a,
        }))
      ),
    [block.groups]
  );

  const visible = useMemo(() => {
    const term = query.trim().toLowerCase();
    return flatItems.filter((it) => {
      if (activeCat !== "all" && it.category !== activeCat) return false;
      if (!term) return true;
      return (
        it.q.toLowerCase().includes(term) ||
        it.a.toLowerCase().includes(term)
      );
    });
  }, [flatItems, query, activeCat]);

  // Regroup visible items by their original group so headings stay in order.
  const grouped = useMemo(() => {
    const map = new Map();
    visible.forEach((it) => {
      if (!map.has(it.groupIndex)) {
        map.set(it.groupIndex, {
          heading: it.groupHeading,
          items: [],
        });
      }
      map.get(it.groupIndex).items.push(it);
    });
    return Array.from(map.entries())
      .sort(([a], [b]) => a - b)
      .map(([, v]) => v);
  }, [visible]);

  return (
    <section id={block.id} className="scroll-mt-28 py-10 md:py-12">
      <div className="container-custom max-w-[860px]">
        <h2 className={h2Cls}>{block.heading}</h2>

        <div className="my-4">
          <label htmlFor="faq-search" className="sr-only">
            Search the questions
          </label>
          <input
            id="faq-search"
            type="search"
            placeholder={block.searchPlaceholder}
            autoComplete="off"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="mb-3.5 w-full rounded-full border-2 border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-950 px-4 py-3 text-base text-gray-900 dark:text-gray-100 placeholder:text-gray-400 focus:border-secondary focus:outline-none"
          />

          <ul aria-label={block.categoryAriaLabel} className="mb-2.5 flex flex-wrap gap-2.5">
            {block.categories.map((c) => (
              <li key={c.key}>
                <button
                  type="button"
                  aria-pressed={c.key === activeCat}
                  onClick={() => setActiveCat(c.key)}
                  className={chipCls(c.key === activeCat)}
                >
                  {c.label}
                </button>
              </li>
            ))}
          </ul>

          <div className="flex flex-wrap items-center justify-between gap-3">
            <p aria-live="polite" className="m-0 text-gray-500 dark:text-gray-400">
              {visible.length} of {flatItems.length} questions
            </p>
            <button
              type="button"
              onClick={() => setAllOpen((o) => !o)}
              className="cursor-pointer border-0 bg-transparent p-0 text-secondary underline underline-offset-2 hover:text-primary"
            >
              {allOpen ? block.collapseLabel : block.expandLabel}
            </button>
          </div>
        </div>

        {grouped.length === 0 && (
          <p className="rounded-xl border-2 border-dashed border-gray-300 dark:border-gray-700 px-5 py-5 text-gray-500 dark:text-gray-400">
            {block.emptyText}
          </p>
        )}

        {grouped.map((g) => (
          <section key={g.heading} className="mt-6">
            <h3 className={`${h3Cls} !text-xl mb-2.5`}>{g.heading}</h3>
            {g.items.map((it) => (
              <details
                key={it.id}
                // `open` is applied at mount and re-applied whenever this
                // component re-renders (e.g. when Expand All is toggled).
                // Individual manual opens are preserved between toggles
                // because React only patches this prop on re-render.
                open={allOpen}
                className="group mb-2.5 overflow-hidden rounded-2xl border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 shadow-sm"
              >
                <summary className="relative cursor-pointer list-none py-4 pl-5 pr-12 font-semibold text-primary dark:text-white [&::-webkit-details-marker]:hidden">
                  {it.q}
                  <span
                    aria-hidden="true"
                    className="absolute right-5 top-1/2 -translate-y-1/2 text-2xl leading-none text-secondary transition-transform group-open:rotate-45"
                  >
                    +
                  </span>
                </summary>
                <div className="px-5 pb-5">
                  <GuideMarkdown md={it.a} live={live} />
                </div>
              </details>
            ))}
          </section>
        ))}
      </div>
    </section>
  );
}